"""Build the local bilingual visual review from executed evidence only."""
from pathlib import Path
import json,html,shutil
R=Path(__file__).resolve().parents[1];E=R.parent.parent/'Evidence/revision_02';D=R.parent/'Review';A=D/'assets';A.mkdir(parents=True,exist_ok=True)
qa=json.loads((E/'ui_validation.json').read_text(encoding='utf-8'));perf=json.loads((E/'performance_smoke.json').read_text())
portable=json.loads((E/'portable_validation.json').read_text()) if (E/'portable_validation.json').exists() else {'status':'PENDING'}
def photo(name,caption):
    shutil.copy2(E/name,A/name)
    return f'<figure><a href="assets/{name}" target="_blank"><img loading="lazy" src="assets/{name}" alt="{html.escape(caption)}"></a><figcaption>{html.escape(caption)}</figcaption></figure>'
def pair(es,en):return f'<p lang="es">{es}</p><p class="english" lang="en">{en}</p>'
blocks=[]
blocks.append('<section><h2>01 / El fallo y la corrección · Failure and repair</h2>'+pair('El HTML anterior no ejecutaba el módulo JavaScript al abrirse como archivo local: cero polígonos. Se sustituyó el arranque por scripts clásicos, un Worker local y cápsulas selectivas verificadas. Ahora el acceso por doble clic muestra 339 municipios y enlaces Español / English.','The previous file entry was blocked by module CORS and rendered zero polygons. Classic scripts, a local Worker and verified selective capsules now load 339 municipalities directly, with visible language links.')+'<div class="grid">'+photo('before_satellites_file.png','Antes / Before: archivo sin aplicación funcional')+photo('final_desktop_es.png','Después / After: apertura directa, Español')+'</div></section>')
blocks.append('<section><h2>02 / Referentes de Agricultura · Agriculture references</h2>'+pair('Comparación con los productos congelados C02 y C04, sin modificarlos. El hero utiliza una ilustración nueva, la misma familia tipográfica y la paleta de interfaz turquesa/rosa.','Read-only comparison with frozen C02 and C04 products. A new illustration follows their type family and teal/rose interface.')+'<div class="grid">'+photo('reference_agriculture_c02.png','Referencia C02 / C02 reference')+photo('reference_agriculture_c04.png','Referencia C04 / C04 reference')+'</div></section>')
blocks.append('<section><h2>03 / Mapa de las mismas dimensiones · Matching map dimensions</h2>'+pair('Medición ejecutada en ventana 1440 × 1000: ambos lienzos son de <strong>820 × 620 px</strong>. Panel lateral de 310 px y geometría exacta de 339 municipios. Selección real en el mapa y Top 10 sincronizados con la serie. Panel: figura y ranking; explicaciones al pie. Referencia fija: 10 noviembre 2025.','Measured at a 1440 × 1000 viewport: both map canvases are <strong>820 × 620 px</strong>, with a 310 px side panel. A real map click opens the complete history.')+'<div class="grid">'+photo('reference_agriculture_c04_map.png','Mapa Agriculture C04 / Agriculture map')+photo('final_chart_top10.png','Satellites: evolución y Top 10 / history and Top 10')+'</div></section>')
blocks.append('<section><h2>04 / Paletas por magnitud · Palettes by magnitude</h2>'+pair('Azul–amarillo–rojo para temperatura; familias propias para lluvia, luces, fuego, NDVI/EVI y PM2.5. Dispersión usa una rampa distinta. Rangos fijos entre fechas, etiquetas originales y faltantes separados. Área quemada y Black Marble se muestran directamente con advertencias: visualización no equivale a certificación científica.','Each magnitude has its own palette. Dispersion has a separate scale; ranges stay fixed across dates, and legends retain original units. Burned area and Black Marble render immediately with persistent warnings, without scientific certification.')+'<div class="grid">'+''.join(photo('palette_'+p+'.png',n) for p,n in [('gpm','Precipitación / Rainfall'),('hku','Luces mensuales / Monthly lights'),('fire','Área quemada / Burned area'),('vegetation','Vegetación / Vegetation'),('pm25','PM2.5'),('blackmarble','Black Marble / Daily lights')])+'</div><p><a href="../BoliviaSatellites/public/docs/visual-design.md">Definiciones y fuente metodológica / Definitions and methodological source</a></p></section>')
blocks.append('<section><h2>Black Marble / 23 variables originales</h2>'+pair('El selector incluye suma, m?nimo, m?ximo, mean0, suma de cuadrados y diagn?sticos. Descarga de suma cotejada con el maestro original.','The selector includes sum, minimum, maximum, mean0, sum of squares and diagnostics. Downloaded sum is checked against the original master.')+photo('blackmarble_sum.png','Black Marble: suma fuente / Source pixel sum')+'</section>')
blocks.append('<section><h2>05 / Idiomas, móvil y trayectorias · Languages, mobile and trajectories</h2><div class="grid">'+photo('final_desktop_en.png','English: hero y navegación / hero and navigation')+photo('daily_339_spaghetti_en.png','339 series diarias progresivas / Progressive daily series')+'</div><div class="phones">'+photo('final_mobile_es.png','Móvil: Español')+photo('final_mobile_en.png','Mobile: English')+photo('final_mobile_map_en.png','Mapa amplio / Large map')+'</div>'+pair('Sin desbordamiento horizontal en 360, 390, 768, 1440 y 1920 px, en ambos idiomas. La reducción visual está advertida; CSV idéntico bajo las tres escalas del mapa.','No horizontal overflow at five tested widths, in either language. Visual reduction is disclosed; CSV bytes remain identical under all three map scales.')+'</section>')
rows=perf['trials'];maxbytes=max(x['http_transferred_bytes'] or 0 for x in rows);maxt=max(x['initial_ms'] for x in rows)
blocks.append('<section><h2>06 / Resultados y límites · Results and limits</h2>'+pair(f'<strong>{len(qa["checks"])} comprobaciones de interfaz PASS</strong>. Doce ensayos fríos de revisión: carga máxima {maxt:.0f} ms; transferencia HTTP máxima {maxbytes:,} bytes. Portable: <strong>{portable["status"]}</strong>.','Twelve current-build smoke trials cover direct file and HTTP, desktop and emulated mobile. These do not replace final p95 or cross-browser certification.')+pair('Los antiguos 80 ensayos se conservan como evidencia histórica. Firefox/WebKit, comparación tecnológica integral y aspectos científicos pendientes siguen abiertos. No se declara aprobado ni cerrado Contract 05.','Earlier 80-trial measurements are historical. Firefox/WebKit, the complete architecture comparison and scientific limitations remain open. Contract 05 is neither accepted nor closed.')+'<p><strong>Distribucion web / Web distribution</strong>. Presupuesto autorizado: 300 MiB para dist y 15.000 archivos; cada ZIP conserva su limite de 250 MiB. Consultar el manifiesto de distribucion vigente y las revisiones de validacion. Authorized budget: 300 MiB total and 15,000 files; ZIP assets remain below 250 MiB. See the current distribution manifest and validation reports.</p><details><summary>Pruebas ejecutadas / Executed checks</summary><table><thead><tr><th>Prueba / Check</th><th>Resultado / Result</th></tr></thead><tbody>'+''.join(f'<tr><td>{html.escape(k)}</td><td class="pass">{v}</td></tr>' for k,v in qa['checks'].items())+'</tbody></table></details><p><a href="../../Evidence/revision_02/ui_validation.json">Evidencia UI / UI evidence</a> · <a href="../../Evidence/revision_02/performance_smoke.json">Mediciones / Measurements</a> · <a href="../../Evidence/revision_02/portable_validation.json">Portable</a> · <a href="MATRIZ_ACEPTACION.md">Matriz contractual / Contract matrix</a></p></section>')
# Latest narrow revision; retain earlier comparisons as historical evidence.
latest=R.parent.parent/'Evidence/revision_04_historical_pool'
if (latest/'validation.json').exists():
    import shutil
    for name in ['temperature_mean_es.png','temperature_mean_en.png','temperature_mean_mobile.png']:
        shutil.copy2(latest/name,D/'assets'/name)
    blocks.insert(0,'<section><h2>Revision 04: escala historica fija / Fixed historical scale</h2><p>Amarillo = media de todo el pool historico; extremos = minimo y maximo historicos. Escala fija entre fechas. Escala lineal en Celsius. Descargas originales.</p><p class="english">Yellow = whole historical pool mean; endpoints = historical minimum and maximum. Fixed across dates. Linear Celsius. Original downloads.</p><div class="grid"><figure><img src="assets/temperature_mean_es.png"><figcaption>ES: minimo -10.54, media 14.23, maximo 31.97 Celsius.</figcaption></figure><figure><img src="assets/temperature_mean_en.png"><figcaption>EN: identical data and mean.</figcaption></figure></div><p><a href="../../Evidence/revision_04_historical_pool/validation.json">159 comprobaciones / 159 checks</a></p><p>Las capturas posteriores conservan la evidencia historica de revision 02. / The following screenshots retain historical revision 02 evidence.</p></section>')
# Current rain palette visual evidence.
rain_review=R.parent.parent/'Evidence/revision_05_rain_palette'
if (rain_review/'visual_check.json').exists():
    for name in ['rain_es.png','rain_en.png','rain_mobile.png']:
        shutil.copy2(rain_review/name,D/'assets'/name)
    blocks.insert(0,'<section><h2>Revision 05: lluvia / Rainfall</h2><p>Marron: poca lluvia. Amarillo: intermedia. Verde azulado: mucha lluvia. Sin blanco. Escala y observaciones conservadas.</p><p class="english">Brown: low rainfall. Yellow: intermediate. Teal: high rainfall. No white. Scale and observations preserved.</p><div class="grid"><figure><img src="assets/rain_es.png"><figcaption>ES</figcaption></figure><figure><img src="assets/rain_en.png"><figcaption>EN</figcaption></figure></div><p><a href="../../Evidence/revision_05_rain_palette/visual_check.json">Verificacion visual / Visual check</a></p></section>')
# Rankings and original-value context, approved definitions revision 06.
context_review=R.parent.parent/'Evidence/revision_06_rankings_context'
if (context_review/'validation.json').exists():
    for name in ['context_es.png','context_en.png','blackmarble_context.png','context_mobile.png','rankings_mobile.png']:
        shutil.copy2(context_review/name,D/'assets'/name)
    blocks.insert(0,'<section><h2>Revision 06: Top / Bottom 10 y contexto</h2><p>Observacion seleccionada, media del pool, media entre municipios del periodo y media historica del municipio. Valores originales, tamanos de muestra y seleccion sincronizada.</p><p class="english">Selected observation, historical pool mean, period mean across municipalities and municipality historical mean. Original values, sample counts and synchronized selection.</p><div class="grid"><figure><img src="assets/context_es.png"><figcaption>ES: mapa y dos rankings / Map and both rankings</figcaption></figure><figure><img src="assets/blackmarble_context.png"><figcaption>EN: Black Marble, daily context</figcaption></figure></div><p><a href="../../Evidence/revision_06_rankings_context/validation.json">500 comprobaciones, 80 variables / 500 checks, 80 variables</a></p></section>')
# Current unboxed map annotations and transform-aware pool centres.
centre_review=R.parent.parent/'Evidence/revision_07_map_space_centres'
if (centre_review/'validation.json').exists():
    for name in ['era5_es_1440.png','gpm_es_1440.png','blackmarble_es_1440.png','era5_en_390.png']:
        shutil.copy2(centre_review/name,D/'assets'/name)
    blocks.insert(0,'<section><h2>Revision 07: espacios del mapa / Map whitespace</h2><p>Cifras sin recuadros alrededor de la silueta. Centro de color = inversa de la media en la escala elegida sobre todo el pool historico. Extremos historicos fijos.</p><p class="english">Unboxed figures around the silhouette. Colour centre = inverse of the full historical pool mean in the selected scale. Fixed historical endpoints.</p><div class="grid"><figure><img src="assets/era5_es_1440.png"><figcaption>Temperatura lineal / Linear temperature</figcaption></figure><figure><img src="assets/blackmarble_es_1440.png"><figcaption>Black Marble: centro logaritmico expresado en unidades originales / Log centre in original units</figcaption></figure></div><p><a href="../../Evidence/revision_07_map_space_centres/validation.json">1383 comprobaciones / 1383 checks; 215 centros validos / valid centres</a></p><p>Las secciones posteriores muestran evidencia historica de revisiones anteriores. / The following sections preserve historical revision evidence.</p></section>')
# Fluid width and inline ranking values, revision 08.
wide_review=R.parent.parent/'Evidence/revision_08_wide_rankings'
if (wide_review/'visual_check.json').exists():
    for name in ['wide_before_1920.png','wide_after_1920.png','wide_en.png','mobile_ranks.png']:
        shutil.copy2(wide_review/name,D/'assets'/name)
    blocks.insert(0,'<section><h2>Revision 08: ancho util y rankings / Width and rankings</h2><p>1920 px: area de trabajo de 1208 a 1843 px. Municipio y valor en la misma fila. Top y Bottom juntos en escritorio; listas apiladas en movil estrecho.</p><p class="english">1920 px: workspace expands from 1208 to 1843 px. Municipality and value share each row. Top and Bottom are side by side on desktop and stacked on narrow phones.</p><div class="grid"><figure><img src="assets/wide_before_1920.png"><figcaption>Antes / Before: stylesheet revision 07, same data</figcaption></figure><figure><img src="assets/wide_after_1920.png"><figcaption>Ahora / After: fluid workspace and inline values</figcaption></figure></div><p><a href="../../Evidence/revision_08_wide_rankings/visual_check.json">Seis anchos / Six widths</a> | <a href="../../Evidence/revision_08_wide_rankings/all_rank_rows.json">80 variables, 160 verificaciones de filas / 160 row checks</a></p></section>')
css='''*{box-sizing:border-box}body{margin:0;background:#071417;color:#e3ecea;font:16px/1.65 system-ui,sans-serif}main{max-width:1280px;padding:36px;margin:auto}header{padding:30px 0;border-bottom:1px solid #284046}h1{font-size:clamp(30px,4vw,50px);line-height:1.15;margin:12px 0}h2{font-size:25px;line-height:1.3;margin-bottom:22px}.eyebrow,.pass{color:#5ad6c6}.english{color:#aac3bc;font-size:.92em}section{padding:35px 0;border-bottom:1px solid #284046}a{color:#5ad6c6;text-underline-offset:4px}.button{display:inline-block;margin:14px 0;padding:12px 20px;border-radius:7px;background:#b73d5c;color:white;text-decoration:none}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.phones{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;max-width:960px;margin:25px auto}figure{margin:0;padding:12px;background:#0c2024;border:1px solid #284046;border-radius:12px}img{width:100%;display:block;border-radius:5px}figcaption{font-size:13px;color:#aac3bc;margin-top:9px}table{width:100%;font-size:13px;border-collapse:collapse}td,th{padding:9px;text-align:left;border-bottom:1px solid #284046;overflow-wrap:anywhere}details{padding:15px;background:#0c2024;border-radius:8px}summary{cursor:pointer}@media(max-width:700px){main{padding:20px}.grid{grid-template-columns:1fr}.phones{gap:8px}h2{font-size:21px}}'''
(D/'CONTROL_CALIDAD_VISUAL.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bolivia Satellites — Control visual / Visual review</title><style>'+css+'</style><main><header><div class="eyebrow">CONTRACT 05 · REVISIÓN LOCAL 02 / LOCAL REVISION 02</div><h1>Bolivia Satellites<br>Control de calidad visual</h1><p class="english">Visual quality review · Compared with Agriculture C02 / C04</p><a class="button" href="../ABRIR_BOLIVIA_SATELLITES.html">Abrir aplicación / Open application</a><p>PENDING HUMAN ACCEPTANCE · Sin publicación / Unpublished</p></header>'+''.join(blocks)+'</main></html>',encoding='utf-8')
print(D/'CONTROL_CALIDAD_VISUAL.html')
